const inputData = $input.item.json;
let rawText = inputData.text || inputData.output || (typeof inputData === 'string' ? inputData : JSON.stringify(inputData));
const cleaned = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();

let g = null;
try { g = JSON.parse(cleaned); } catch (e) { g = null; }

let src = {};
try { src = $('Loop Over Items').item.json; } catch (err) { src = {}; }

// Pass Claude/seed fields straight through, untouched.
const pass = {
  idea_id: src.idea_id || "",
  category_id: src.category_id || "",
  category_name: src.category_name || "",
  category_slug: src.category_slug || "",
  subcategory_id: src.subcategory_id || "",
  subcategory_name: src.subcategory_name || "",
  subcategory_slug: src.subcategory_slug || "",
  focus_keyword: src.focus_keyword || "",
  additional_keyword_1: src.additional_keyword_1 || "",
  additional_keyword_2: src.additional_keyword_2 || "",
  business_description: src.business_description || "",
  collection_id: src.collection_id || "",
  title: src.title || "",
  slug: src.slug || "",
  seo_title: src.seo_title || "",
  meta_description: src.meta_description || "",
  tags: src.tags || "[]",
  external_links: src.external_links || "[]",
  internal_link_anchors: src.internal_link_anchors || "[]",
  research_facts: src.research_facts || "{}"
};

// If Gemini failed, mark for retry but KEEP all of Claude's work intact.
if (!g || !g.summary) {
  return { json: { ...pass, status: "needs_retry" } };
}

const str = (v) => (v === undefined || v === null) ? "" : String(v);
const arr = (v) => Array.isArray(v) ? JSON.stringify(v) : (typeof v === 'string' ? v : JSON.stringify(v || []));
const trend = parseInt(g.trend_score, 10) || 70;
const tier = g.tier || (trend >= 88 ? "premium" : "free");

return {
  json: {
    ...pass,
    summary: str(g.summary),
    market_opportunity: str(g.market_opportunity),
    target_customer: str(g.target_customer),
    how_you_make_money: str(g.how_you_make_money),
    startup_cost: str(g.startup_cost),
    income_potential: str(g.income_potential),
    competition_edge: str(g.competition_edge),
    getting_started_steps: arr(g.getting_started_steps),
    tools_needed: arr(g.tools_needed),
    time_to_first_customer: str(g.time_to_first_customer),
    faq_json: arr(g.faq_json),
    pros_json: arr(g.pros_json),
    cons_json: arr(g.cons_json),
    verdict: str(g.verdict),
    trend_score: trend,
    tier: tier,
    status: "completed"
  }
};

// Turn the raw ideas rows into one item per category.
//
// Deliberately derived from the live table rather than from a hardcoded list
// of 14 slugs: categories will be added, and a pipeline that has to be edited
// every time one appears is a pipeline that silently goes stale.
const rows = $input.all().map((i) => i.json);
if (rows.length === 0) {
  throw new Error('No completed ideas came back from Supabase. Check the filter and the credential.');
}

const byCat = new Map();
for (const r of rows) {
  if (!r.category_slug) continue;
  let c = byCat.get(r.category_slug);
  if (!c) {
    c = { category_slug: r.category_slug, category_name: r.category_name, idea_count: 0, titles: [] };
    byCat.set(r.category_slug, c);
  }
  c.idea_count += 1;
  if (c.titles.length < 12 && r.title) c.titles.push(r.title);
}

// Optional narrowing: set ONLY_CATEGORY in the n8n environment to run a
// single category first and read the output before spending keys on all 14.
const only = $env.ONLY_CATEGORY;

return [...byCat.values()]
  .filter((c) => !only || c.category_slug === only)
  .map((c) => ({
    json: {
      category_slug: c.category_slug,
      category_name: c.category_name,
      idea_count: c.idea_count,
      sample_titles: c.titles.map((t) => `- ${t}`).join('\n'),
    },
  }));

// Gemini API key rotation.
//
// N8N_PIPELINE_PLAN.md lists this as a hard constraint and it was never
// built: a single exhausted key stalled an entire batch. Keys live in the
// n8n environment as GEMINI_API_KEY_1 ... GEMINI_API_KEY_7 so none of them
// is ever written into this file or into the repository.
//
// The index advances on every call and is carried in workflow static data,
// so it survives between runs. A 429 or 5xx on the HTTP node retries, and
// because this node re-runs it, the retry lands on the NEXT key rather than
// hammering the exhausted one.
const keys = [];
for (let i = 1; i <= 7; i++) {
  const k = $env[`GEMINI_API_KEY_${i}`];
  if (k) keys.push(k);
}
if (keys.length === 0) {
  throw new Error(
    'No Gemini keys found. Set GEMINI_API_KEY_1..7 in the n8n environment. ' +
    'Never paste a key into a node parameter -- it would end up in the exported JSON.'
  );
}

const store = $getWorkflowStaticData('global');
store.geminiKeyIndex = (store.geminiKeyIndex ?? 0) % keys.length;

const out = [];
for (const item of $input.all()) {
  const key = keys[store.geminiKeyIndex];
  store.geminiKeyIndex = (store.geminiKeyIndex + 1) % keys.length;
  out.push({
    json: {
      ...item.json,
      geminiKey: key,
      geminiKeyNumber: keys.indexOf(key) + 1,
      geminiKeyCount: keys.length,
    },
  });
}
return out;

// Parse Gemini's JSON array into one n8n item per FAQ, so the Supabase node
// inserts twelve rows rather than one row holding an array.
//
// Every check below rejects the whole batch for that category rather than
// writing partial or malformed content. A bad row in this table shows up on
// a public page, and the site has already had to strip invented content four
// separate times.
const BANNED_VENDORS = /\b(claude|perplexity|chatgpt|openai|grok|gemini|copilot)\b/i;
const YEAR = /\b(19|20)\d{2}\b/;
const EMOJI = /[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}]/u;

const out = [];

for (const item of $input.all()) {
  const cat = $('Distinct Categories').item.json;

  let raw = item.json.candidates?.[0]?.content?.parts?.[0]?.text;
  if (typeof raw !== 'string') {
    throw new Error(`No text back from Gemini for ${cat.category_slug}. Full response: ${JSON.stringify(item.json).slice(0, 500)}`);
  }

  // Strip fences if the model added them despite being told not to.
  raw = raw.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();

  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    throw new Error(`Gemini returned non-JSON for ${cat.category_slug}: ${raw.slice(0, 300)}`);
  }

  if (!Array.isArray(parsed)) throw new Error(`Expected an array for ${cat.category_slug}, got ${typeof parsed}`);
  if (parsed.length < 8) throw new Error(`Only ${parsed.length} FAQs for ${cat.category_slug}; expected 12. Not writing a thin pool.`);

  const seen = new Set();

  for (const row of parsed) {
    const q = String(row.question ?? '').trim();
    const a = String(row.answer ?? '').trim();

    if (!q || !a) throw new Error(`Empty question or answer in ${cat.category_slug}`);
    if (BANNED_VENDORS.test(q) || BANNED_VENDORS.test(a)) {
      throw new Error(`Named an AI vendor in ${cat.category_slug}: ${q.slice(0, 80)}`);
    }
    if (YEAR.test(q) || YEAR.test(a)) {
      throw new Error(`Contains a year in ${cat.category_slug}: ${q.slice(0, 80)}`);
    }
    if (EMOJI.test(q) || EMOJI.test(a)) {
      throw new Error(`Contains an emoji in ${cat.category_slug}: ${q.slice(0, 80)}`);
    }
    const wordCount = a.split(/\s+/).length;
    if (wordCount < 25 || wordCount > 130) {
      throw new Error(`Answer is ${wordCount} words in ${cat.category_slug}; wanted 40-90. Q: ${q.slice(0, 60)}`);
    }
    const key = q.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
    if (seen.has(key)) throw new Error(`Duplicate question inside ${cat.category_slug}: ${q.slice(0, 80)}`);
    seen.add(key);

    out.push({ json: { category_slug: cat.category_slug, question: q, answer: a, is_active: true } });
  }
}

return out;

// Gemini API key rotation.
//
// N8N_PIPELINE_PLAN.md lists this as a hard constraint and it was never
// built: a single exhausted key stalled an entire batch. Keys live in the
// n8n environment as GEMINI_API_KEY_1 ... GEMINI_API_KEY_7 so none of them
// is ever written into this file or into the repository.
//
// The index advances on every call and is carried in workflow static data,
// so it survives between runs. A 429 or 5xx on the HTTP node retries, and
// because this node re-runs it, the retry lands on the NEXT key rather than
// hammering the exhausted one.
const keys = [];
for (let i = 1; i <= 7; i++) {
  const k = $env[`GEMINI_API_KEY_${i}`];
  if (k) keys.push(k);
}
if (keys.length === 0) {
  throw new Error(
    'No Gemini keys found. Set GEMINI_API_KEY_1..7 in the n8n environment. ' +
    'Never paste a key into a node parameter -- it would end up in the exported JSON.'
  );
}

const store = $getWorkflowStaticData('global');
store.geminiKeyIndex = (store.geminiKeyIndex ?? 0) % keys.length;

const out = [];
for (const item of $input.all()) {
  const key = keys[store.geminiKeyIndex];
  store.geminiKeyIndex = (store.geminiKeyIndex + 1) % keys.length;
  out.push({
    json: {
      ...item.json,
      geminiKey: key,
      geminiKeyNumber: keys.indexOf(key) + 1,
      geminiKeyCount: keys.length,
    },
  });
}
return out;

// Parse Gemini's JSON and refuse anything that would publish badly.
//
// The model is asked for raw JSON, but it still occasionally wraps the object
// in a markdown fence, so strip that before parsing rather than failing the
// whole batch on a formatting quirk.
const out = [];

for (const item of $input.all()) {
  const raw = item.json?.candidates?.[0]?.content?.parts?.[0]?.text ?? '';
  const cleaned = String(raw).replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();

  let post;
  try {
    post = JSON.parse(cleaned);
  } catch (e) {
    throw new Error('Gemini did not return valid JSON for "' + (item.json.title ?? 'unknown row') + '": ' + e.message);
  }

  const need = ['title', 'slug', 'excerpt', 'content_html', 'image_prompt', 'meta_description'];
  const missing = need.filter((k) => !post[k] || String(post[k]).trim() === '');
  if (missing.length) throw new Error('Post is missing required fields: ' + missing.join(', '));

  // Guards. Each of these has shipped as a real defect on this project before.
  if (/<h1[\s>]/i.test(post.content_html)) throw new Error('content_html contains an <h1>; the theme renders the title.');
  if (/<script|<style|onerror=|onclick=/i.test(post.content_html)) throw new Error('content_html contains script/style/handlers.');
  if (String(post.title).length > 80) throw new Error('Title too long: ' + post.title.length);
  if (String(post.meta_description).length > 165) throw new Error('meta_description too long: ' + post.meta_description.length);

  const words = String(post.content_html).replace(/<[^>]+>/g, ' ').split(/\s+/).filter(Boolean).length;
  if (words < 350) throw new Error('Post is only ' + words + ' words; too thin to publish.');

  post.slug = String(post.slug).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

  out.push({ json: { ...item.json, post, wordCount: words } });
}

return out;

// Gemini returns the image as base64 inside inlineData. n8n's WordPress media
// endpoint needs real binary, so convert it here.
const out = [];
for (const item of $input.all()) {
  const parts = item.json?.candidates?.[0]?.content?.parts ?? [];
  const img = parts.find((p) => p.inlineData?.data);
  if (!img) {
    // No image is not a reason to lose the post. Publish without a cover and
    // say so on the sheet row instead of throwing the whole run away.
    out.push({ json: { ...item.json, coverMissing: true } });
    continue;
  }
  out.push({
    json: { ...item.json, coverMissing: false },
    binary: {
      cover: await this.helpers.prepareBinaryData(
        Buffer.from(img.inlineData.data, 'base64'),
        (item.json.post?.slug ?? 'cover') + '.png',
        img.inlineData.mimeType || 'image/png',
      ),
    },
  });
}
return out;
